proof fn capacity_domain(n: nat, s: nat)
    ensures
        (n <= 3 * (s / 4)) == (encoded_size(n) <= s),
        n <= encoded_size(n),
        decoded_estimate(encoded_size(n)) == 3 * groups(n),
        n <= decoded_estimate(encoded_size(n)) <= n + 2,
{
