    assert(s == 4 * (s / 4) + s % 4) by (nonlinear_arith);
    assert(n % 3 < 3 && s % 4 < 4) by (nonlinear_arith);
    assert((4 * groups(n)) / 4 == groups(n)) by (nonlinear_arith);
    assert((4 * groups(n)) % 4 == 0) by (nonlinear_arith);
}
}
