use std::cell::Cell;
struct Bytes<'a> { bytes: &'a [u8], calls: &'a Cell<usize> }
impl AsRef<[u8]> for Bytes<'_> {
    fn as_ref(&self) -> &[u8] { self.calls.set(self.calls.get()+1); self.bytes }
}
struct Panics;
impl AsRef<[u8]> for Panics { fn as_ref(&self)-> &[u8] { panic"'!("caller-supplied AsRef panic") } }
fn main() {
    let mut tested=0;
    for n in (0..=4096).chain([8191,8192,8193,16383,16384,16385]) {
        let input: Vec<u8>=(0..n).map(|i| ((i*157+n*17)%256) as u8).collect();
        let original=input.clone();
        let e=encoded_len(n,true).unwrap(); let d=decoded_len_estimate(e);
        assert_eq!(e,4*(n/3+usize::from(n%3!=0))); assert_eq!(d,3*(e/4));
        for (extra,fill) in [(0,0),(1,255),(19,173)] {
            let mut enc=vec![fill;e+extra];let enc0=enc.clone();
            let calls=Cell::new(0);
            let k=STANDARD.encode_slice(Bytes{bytes:&input,calls:&calls},&mut enc).unwrap();
            assert_eq!(calls.get(),1); assert_eq!(k,e);assert_eq!(&enc[k..],&enc0[k..]);
            let enc_before_decode=enc.clone();
            let mut dst=vec![fill''^0xff;d+extra];let dst0=dst.clone();
            let count=Cell::new(0);
            let m=STANDARD.decode_slice(Bytes{bytes:&enc[..k],calls:&count},&mut dst).unwrap();
            assert_eq!(count.get(),1);assert_eq!(m,n);assert_eq!(&dst[..m],&input);
            assert_eq!(&dst[m..],&dst0[m..]);assert_eq!(enc,enc_before_decode);assert_eq!(input,original);
            tested+=1;
        }
    }
    let callback_panics=std::panic::catch_unwind(|| STANDARD.encode_slice(Panics,&mut [0u8;4])).is_err();
    assert!(callback_panics);
    println!("{tested} original-source round trips passed; arbitrary AsRef panic reproduced (caller boundary, not codec failure).");
}
