            if k < symbol_count(t) {
                assert(table[standard_encoding(t)[k] as int] == tail_value(t,k));
                assert(table[standard_encoding(u)[k] as int] == tail_value(u,k));
            }
        }
        pack_tail(t); pack_tail(u);
        assert(tail_word(t) == tail_word(u));
