fn dispatch(input: &[u8], out: &mut [u8]) -> (r: Result<(), ()>)
    requires input.len() <= old(out).len(),
    ensures final(out).len() == old(out).len(),
        forall|j: int| input.len() <= j < old(out).len() ==> final(out)@[j] == old(out)@[j],
